/*
 * Research TD-PSOLA chromatic pitch-correction prototype.
 *
 * Research basis: E. Moulines and F. Charpentier,
 * "Pitch-synchronous waveform processing techniques for text-to-speech
 * synthesis using diphones," Speech Communication 9(5-6), 1990,
 * doi:10.1016/0167-6393(90)90021-Z.
 *
 * This project implementation was written specifically for audible algorithm
 * comparison; no third-party PSOLA source code is copied into this file.
 */
#include "td_psola_autotune.h"
#include "pitch_detector.h"

#include <math.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define TD_FRAME_SIZE                 2048U
#define TD_HOP_SIZE                    512U
#define TD_PITCH_DECIMATION              4U
#define TD_PITCH_RATE_HZ             12000.0f
#define TD_ANALYSIS_SAMPLES            512U
#define TD_MAX_MARKS                    64U
#define TD_PI                   3.14159265358979323846f
#define TD_A4_HZ                440.0f
#define TD_A4_MIDI               69.0f
#define TD_SEMITONES_PER_OCTAVE  12.0f
#define TD_MIN_RMS                120.0f
#define TD_MAX_CORRECTION_RATIO     1.0300f
#define TD_MIN_CORRECTION_RATIO     0.9700f
#define TD_NOTE_HYSTERESIS_CENTS   58.0f
#define TD_PITCH_SMOOTHING          0.32f
#define TD_TARGET_CONFIRM_FRAMES       2U
#define TD_PEAK_SEARCH_FRACTION      0.22f
#define TD_DRY_BLEND_UNVOICED         1.0f

static float td_clampf(float x, float lo, float hi)
{
    if (x < lo) return lo;
    if (x > hi) return hi;
    return x;
}

static int16_t td_saturate_i16(float value)
{
    if (value > 32767.0f) return INT16_MAX;
    if (value < -32768.0f) return INT16_MIN;
    return (int16_t)lrintf(value);
}

void TdPsola_DefaultConfig(TdPsolaConfig *config)
{
    if (config == NULL) return;
    config->strength = 0.90f;
    config->confidence_threshold = 0.68f;
    config->min_pitch_hz = 80.0f;
    config->max_pitch_hz = 500.0f;
}

float TdPsola_ChromaticTargetHz(float input_hz)
{
    if ((!isfinite(input_hz)) || (input_hz <= 0.0f)) return 0.0f;

    const float midi = TD_A4_MIDI
                     + TD_SEMITONES_PER_OCTAVE * log2f(input_hz / TD_A4_HZ);
    const float nearest = roundf(midi);
    return TD_A4_HZ * powf(2.0f, (nearest - TD_A4_MIDI) / TD_SEMITONES_PER_OCTAVE);
}

static bool td_config_valid(const TdPsolaConfig *config)
{
    return (config != NULL)
        && isfinite(config->strength)
        && isfinite(config->confidence_threshold)
        && isfinite(config->min_pitch_hz)
        && isfinite(config->max_pitch_hz)
        && (config->strength >= 0.0f)
        && (config->strength <= 1.0f)
        && (config->confidence_threshold >= 0.0f)
        && (config->confidence_threshold <= 1.0f)
        && (config->min_pitch_hz >= 60.0f)
        && (config->max_pitch_hz <= 1000.0f)
        && (config->min_pitch_hz < config->max_pitch_hz);
}

static int td_find_abs_peak_buffer(const int16_t *samples,
                                   size_t sample_count,
                                   int centre,
                                   int radius)
{
    int start = centre - radius;
    int end = centre + radius;
    if (start < 0) start = 0;
    if (end >= (int)sample_count) end = (int)sample_count - 1;
    if (centre < start) centre = start;
    if (centre > end) centre = end;

    int best = centre;
    int best_abs = -1;
    for (int i = start; i <= end; ++i)
    {
        int value = (int)samples[i];
        if (value < 0) value = -value;
        if (value > best_abs)
        {
            best_abs = value;
            best = i;
        }
    }
    return best;
}

static size_t td_track_index_for_sample(size_t sample, size_t track_count)
{
    size_t index = sample / TD_HOP_SIZE;
    if (index >= track_count) index = track_count - 1U;
    return index;
}

static void td_add_psola_grain(const int16_t *input,
                               size_t sample_count,
                               float *accumulation,
                               float *weights,
                               int analysis_mark,
                               int synthesis_mark,
                               float period)
{
    int radius = (int)lrintf(period);
    if (radius < 16) radius = 16;
    if (radius > 600) radius = 600;

    for (int k = -radius; k <= radius; ++k)
    {
        const int src = analysis_mark + k;
        const int dst = synthesis_mark + k;
        if ((src < 0) || (dst < 0)
            || (src >= (int)sample_count) || (dst >= (int)sample_count))
        {
            continue;
        }

        const float phase = ((float)(k + radius)) / (float)(2 * radius);
        const float window = 0.5f - 0.5f * cosf(2.0f * TD_PI * phase);
        accumulation[dst] += window * (float)input[src];
        weights[dst] += window;
    }
}

/* Build pitch marks for one contiguous voiced region using the local pitch track. */
static size_t td_build_segment_marks(const int16_t *input,
                                     size_t sample_count,
                                     size_t segment_start,
                                     size_t segment_end,
                                     const float *pitch_track,
                                     const uint8_t *voiced_track,
                                     size_t track_count,
                                     int *marks,
                                     size_t max_marks)
{
    if ((segment_start >= segment_end) || (max_marks == 0U)) return 0U;

    const size_t first_track = td_track_index_for_sample(segment_start, track_count);
    if (voiced_track[first_track] == 0U) return 0U;
    float period = (float)TD_PSOLA_SAMPLE_RATE_HZ / pitch_track[first_track];
    if ((!isfinite(period)) || (period < 20.0f) || (period > 800.0f)) return 0U;

    int predicted = (int)segment_start + (int)lrintf(period);
    if (predicted >= (int)segment_end) return 0U;
    int search = (int)lrintf(period * 0.45f);
    if (search < 4) search = 4;
    int current = td_find_abs_peak_buffer(input, sample_count, predicted, search);
    if ((current < (int)segment_start) || (current >= (int)segment_end)) return 0U;

    size_t count = 0U;
    marks[count++] = current;

    while (count < max_marks)
    {
        const size_t track = td_track_index_for_sample((size_t)current, track_count);
        if (voiced_track[track] == 0U) break;
        period = (float)TD_PSOLA_SAMPLE_RATE_HZ / pitch_track[track];
        search = (int)lrintf(period * TD_PEAK_SEARCH_FRACTION);
        if (search < 3) search = 3;
        predicted = current + (int)lrintf(period);
        if (predicted >= (int)segment_end) break;
        const int next = td_find_abs_peak_buffer(input, sample_count, predicted, search);
        if ((next <= current) || (next >= (int)segment_end)) break;
        marks[count++] = next;
        current = next;
    }
    return count;
}

TdPsolaStatus TdPsola_ProcessBuffer(const int16_t *input,
                                    int16_t *output,
                                    size_t sample_count,
                                    const TdPsolaConfig *config_in,
                                    TdPsolaStats *stats)
{
    TdPsolaConfig default_config;
    const TdPsolaConfig *config = config_in;

    if ((input == NULL) || (output == NULL)) return TD_PSOLA_STATUS_NULL_POINTER;
    if (sample_count == 0U) return TD_PSOLA_STATUS_INVALID_LENGTH;

    if (config == NULL)
    {
        TdPsola_DefaultConfig(&default_config);
        config = &default_config;
    }
    if (!td_config_valid(config)) return TD_PSOLA_STATUS_INVALID_CONFIG;

    const size_t track_count = (sample_count + TD_HOP_SIZE - 1U) / TD_HOP_SIZE;
    const size_t max_marks = sample_count / 32U + 8U;

    float *accumulation = (float *)calloc(sample_count, sizeof(float));
    float *weights = (float *)calloc(sample_count, sizeof(float));
    float *pitch_track = (float *)calloc(track_count, sizeof(float));
    float *ratio_track = (float *)calloc(track_count, sizeof(float));
    uint8_t *voiced_track = (uint8_t *)calloc(track_count, sizeof(uint8_t));
    int *marks = (int *)calloc(max_marks, sizeof(int));
    if ((accumulation == NULL) || (weights == NULL) || (pitch_track == NULL)
        || (ratio_track == NULL) || (voiced_track == NULL) || (marks == NULL))
    {
        free(accumulation);
        free(weights);
        free(pitch_track);
        free(ratio_track);
        free(voiced_track);
        free(marks);
        return TD_PSOLA_STATUS_ALLOCATION_FAILED;
    }

    TdPsolaStats local_stats;
    memset(&local_stats, 0, sizeof(local_stats));
    local_stats.minimum_applied_ratio = 1.0f;
    local_stats.maximum_applied_ratio = 1.0f;

    float smoothed_pitch = 0.0f;
    float held_target = 0.0f;
    float pending_target = 0.0f;
    unsigned pending_count = 0U;

    /* First pass: reuse the project's already-tested streaming autocorrelation detector. */
    PitchDetector detector;
    PitchDetector_Init(&detector);
    size_t detector_position = 0U;

    for (size_t frame_index = 0U; frame_index < track_count; ++frame_index)
    {
        const size_t target_position = ((frame_index + 1U) * TD_HOP_SIZE < sample_count)
                                     ? (frame_index + 1U) * TD_HOP_SIZE
                                     : sample_count;
        float pitch = 0.0f;
        float confidence = 0.0f;
        bool valid = false;

        while (detector_position < target_position)
        {
            size_t block = target_position - detector_position;
            if (block > 64U) block = 64U;
            valid = PitchDetector_ProcessBlock(&detector,
                                               input + detector_position,
                                               block,
                                               &pitch,
                                               &confidence);
            detector_position += block;
        }

        local_stats.analysis_frames++;
        if (valid && (confidence >= config->confidence_threshold)
            && (pitch >= config->min_pitch_hz) && (pitch <= config->max_pitch_hz))
        {
            voiced_track[frame_index] = 1U;
            local_stats.voiced_frames++;
            if (smoothed_pitch <= 0.0f) smoothed_pitch = pitch;
            else smoothed_pitch += TD_PITCH_SMOOTHING * (pitch - smoothed_pitch);

            const float candidate = TdPsola_ChromaticTargetHz(smoothed_pitch);
            if (held_target <= 0.0f)
            {
                held_target = candidate;
                pending_target = 0.0f;
                pending_count = 0U;
            }
            else if (candidate != held_target)
            {
                const float cents = 1200.0f * log2f(smoothed_pitch / held_target);
                if (fabsf(cents) >= TD_NOTE_HYSTERESIS_CENTS)
                {
                    if (candidate == pending_target) pending_count++;
                    else
                    {
                        pending_target = candidate;
                        pending_count = 1U;
                    }
                    if (pending_count >= TD_TARGET_CONFIRM_FRAMES)
                    {
                        held_target = candidate;
                        pending_target = 0.0f;
                        pending_count = 0U;
                    }
                }
                else
                {
                    pending_target = 0.0f;
                    pending_count = 0U;
                }
            }
            else
            {
                pending_target = 0.0f;
                pending_count = 0U;
            }

            const float full_ratio = td_clampf(held_target / smoothed_pitch,
                                               TD_MIN_CORRECTION_RATIO,
                                               TD_MAX_CORRECTION_RATIO);
            const float ratio = powf(full_ratio, config->strength);
            pitch_track[frame_index] = smoothed_pitch;
            ratio_track[frame_index] = ratio;

            local_stats.mean_detected_pitch_hz += pitch;
            local_stats.mean_target_pitch_hz += held_target;
            if (ratio < local_stats.minimum_applied_ratio) local_stats.minimum_applied_ratio = ratio;
            if (ratio > local_stats.maximum_applied_ratio) local_stats.maximum_applied_ratio = ratio;
        }
        else
        {
            voiced_track[frame_index] = 0U;
            pitch_track[frame_index] = 0.0f;
            ratio_track[frame_index] = 1.0f;
            smoothed_pitch = 0.0f;
            held_target = 0.0f;
            pending_target = 0.0f;
            pending_count = 0U;
        }
    }

    /* Second pass: process each contiguous voiced region with global TD-PSOLA. */
    size_t track = 0U;
    while (track < track_count)
    {
        while ((track < track_count) && (voiced_track[track] == 0U)) track++;
        if (track >= track_count) break;
        const size_t run_start = track;
        while ((track < track_count) && (voiced_track[track] != 0U)) track++;
        const size_t run_end = track;

        size_t segment_start = run_start * TD_HOP_SIZE;
        size_t segment_end = run_end * TD_HOP_SIZE + TD_FRAME_SIZE;
        if (segment_end > sample_count) segment_end = sample_count;
        if (segment_start >= segment_end) continue;

        const size_t mark_count = td_build_segment_marks(input, sample_count,
                                                         segment_start, segment_end,
                                                         pitch_track, voiced_track,
                                                         track_count, marks, max_marks);
        if (mark_count < 3U) continue;

        float synth_position = (float)marks[0];
        size_t analysis_index = 0U;
        while (synth_position < (float)marks[mark_count - 1U])
        {
            const size_t synth_sample = (size_t)lrintf(synth_position);
            const size_t local_track = td_track_index_for_sample(synth_sample, track_count);
            if (voiced_track[local_track] == 0U) break;

            const float period = (float)TD_PSOLA_SAMPLE_RATE_HZ / pitch_track[local_track];
            const float ratio = ratio_track[local_track];
            const float synthesis_period = period / ratio;

            while ((analysis_index + 1U < mark_count)
                   && (fabsf((float)marks[analysis_index + 1U] - synth_position)
                       < fabsf((float)marks[analysis_index] - synth_position)))
            {
                analysis_index++;
            }

            td_add_psola_grain(input, sample_count, accumulation, weights,
                               marks[analysis_index], (int)lrintf(synth_position), period);
            synth_position += synthesis_period;
        }
    }

    /* Dry fallback handles unvoiced speech, silence and segment edges naturally. */
    for (size_t i = 0U; i < sample_count; ++i)
    {
        if (weights[i] > 0.15f) output[i] = td_saturate_i16(accumulation[i] / weights[i]);
        else output[i] = input[i];
    }

    if (local_stats.voiced_frames > 0U)
    {
        const float denom = (float)local_stats.voiced_frames;
        local_stats.mean_detected_pitch_hz /= denom;
        local_stats.mean_target_pitch_hz /= denom;
    }
    if (stats != NULL) *stats = local_stats;

    free(accumulation);
    free(weights);
    free(pitch_track);
    free(ratio_track);
    free(voiced_track);
    free(marks);
    return TD_PSOLA_STATUS_OK;
}
